                  </p>
                </CardContent>

                {/* Connector */}
                {index < steps.length - 1 && (
                  <div className="hidden lg:block absolute -right-4 top-1/2 -translate-y-1/2 w-8 h-px bg-gradient-to-r from-red-600 to-transparent opacity-30" />
                )}
              </Card>
