"use client";

import { useState, useEffect } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Loader } from "@/components/ui/loader";
import {
  checkEmailExists,
  login,
  signup,
  setUsername,
  type AuthResponse,
} from "@/lib/api";
import { validatePassword } from "@/lib/utils";

interface AuthModalProps {
  isOpen: boolean;
  onClose: () => void;
  onAuthSuccess?: (user: AuthResponse["user"], token: string) => void;
}

type AuthStep = "email" | "password" | "signup-password" | "username" | "success";

export function AuthModal({ isOpen, onClose, onAuthSuccess }: AuthModalProps) {
  const [step, setStep] = useState<AuthStep>("email");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [username, setUsernameState] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [authToken, setAuthToken] = useState("");
  const [isLogin, setIsLogin] = useState(false);

  // Password validation state
  const passwordValidation = validatePassword(password);
  const passwordsMatch = password === confirmPassword && confirmPassword.length > 0;

  // Reset state when modal opens/closes
  useEffect(() => {
    if (!isOpen) {
      setTimeout(() => {
        setStep("email");
        setEmail("");
        setPassword("");
        setConfirmPassword("");
        setUsernameState("");
        setError("");
        setAuthToken("");
        setIsLogin(false);
      }, 300);
    }
  }, [isOpen]);

  const handleEmailSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError("");
    setLoading(true);

    try {
      const result = await checkEmailExists(email);
      if (result.exists) {
        setIsLogin(true);
        setStep("password");
      } else {
        setIsLogin(false);
        setStep("signup-password");
      }
    } catch (err) {
      setError("Failed to check email. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  const handleLoginPasswordSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError("");
    setLoading(true);

    try {
      const result = await login(email, password);
      setAuthToken(result.token);
      setStep("success");
      onAuthSuccess?.(result.user, result.token);

      // Store token in localStorage
      localStorage.setItem("auth_token", result.token);
      localStorage.setItem("user", JSON.stringify(result.user));

      setTimeout(() => {
        onClose();
      }, 2000);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to login");
    } finally {
      setLoading(false);
    }
  };

  const handleSignupPasswordSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError("");

    if (!passwordValidation.isValid) {
      setError("Password does not meet requirements");
      return;
    }

    if (!passwordsMatch) {
      setError("Passwords do not match");
      return;
    }

    setLoading(true);

    try {
      const result = await signup(email, password);
      setAuthToken(result.token);
      setStep("username");

      // Temporarily store token for username step
      localStorage.setItem("auth_token_temp", result.token);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to signup");
    } finally {
      setLoading(false);
    }
  };

  const handleUsernameSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError("");

    const cleanUsername = username.replace("@", "").trim();

    if (cleanUsername.length < 3) {
      setError("Username must be at least 3 characters");
      return;
    }

    setLoading(true);

    try {
      const token = localStorage.getItem("auth_token_temp");
      if (!token) {
        throw new Error("Authentication token not found");
      }

      const result = await setUsername(`@${cleanUsername}`, email, token);

      // Update stored user data
      const user = {
        id: result.user.id,
        email: result.user.email,
        username: result.user.username,
      };
      localStorage.setItem("user", JSON.stringify(user));
      localStorage.setItem("auth_token", token);
      localStorage.removeItem("auth_token_temp");

      setAuthToken(token);
      setStep("success");
      onAuthSuccess?.(user, token);

      setTimeout(() => {
        onClose();
      }, 2000);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to set username");
    } finally {
      setLoading(false);
    }
  };

  const handleBackdropClick = (e: React.MouseEvent<HTMLDivElement>) => {
    if (e.target === e.currentTarget) {
      onClose();
    }
  };

