    },
    body: JSON.stringify(data),
  });

  if (!response.ok) {
    throw new Error("Failed to join waitlist");
  }

  return response.json();
}

// Auth types
export interface AuthExistsRequest {
  email: string;
}

export interface AuthExistsResponse {
  exists: boolean;
}

export interface AuthLoginRequest {
  email: string;
  password: string;
}

export interface AuthSignupRequest {
  email: string;
  password: string;
}

export interface AuthResponse {
  token: string;
  user: {
    id: string;
    email: string;
    username?: string;
  };
}

export interface AuthUsernameRequest {
  username: string;
  email: string;
}

export interface AuthUsernameResponse {
  success: boolean;
  message: string;
  user: {
    id: string;
    email: string;
    username: string;
  };
}

// Mock delay helper
const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

// Mock data store (for testing)
const mockUsers = new Map<string, { email: string; password: string; username?: string; id: string }>();

// Auth API functions (MOCKED for testing)
export async function checkEmailExists(email: string): Promise<AuthExistsResponse> {
  await delay(800); // Simulate network delay

  // Mock: emails ending with "existing" are treated as existing users
  const exists = email.toLowerCase().includes("existing") || mockUsers.has(email);
  return { exists };
}

export async function login(email: string, password: string): Promise<AuthResponse> {
  await delay(1000); // Simulate network delay

  // Mock validation
  if (!email || !password) {
    throw new Error("Email and password are required");
  }

  if (password !== "Password1!") {
    throw new Error("Invalid credentials");
  }

  const mockUser = {
    id: "user_" + Math.random().toString(36).slice(2),
    email,
    username: mockUsers.get(email)?.username,
  };

  return {
    token: "mock_jwt_token_" + Math.random().toString(36).slice(2),
    user: mockUser,
  };
}

export async function signup(email: string, password: string): Promise<AuthResponse> {
  await delay(1000); // Simulate network delay

  // Mock validation
  if (!email || !password) {
    throw new Error("Email and password are required");
  }

  // Store mock user
  const mockUser = {
    id: "user_" + Math.random().toString(36).slice(2),
    email,
  };
  mockUsers.set(email, { ...mockUser, password });

  return {
    token: "mock_jwt_token_" + Math.random().toString(36).slice(2),
    user: mockUser,
  };
}

export async function setUsername(username: string, email: string, token: string): Promise<AuthUsernameResponse> {
  await delay(800); // Simulate network delay

  // Mock validation
  if (!username || username.length < 3) {
    throw new Error("Username must be at least 3 characters");
  }

  // Update mock user
  const existingUser = mockUsers.get(email);
  if (existingUser) {
    existingUser.username = username;
    mockUsers.set(email, existingUser);
  }

  return {
    success: true,
    message: "Username set successfully",
    user: {
      id: existingUser?.id || "user_mock",
      email,
      username,
    },
  };
}

export async function logout(token: string): Promise<void> {
  await delay(500); // Simulate network delay
  // Mock logout - just clear from mock store
}

