              {isLogin ? "Welcome Back!" : "Account Created!"}
            </h3>
            <p className="text-gray-400 text-sm">
              {isLogin ? "You have successfully logged in" : "Your account has been created successfully"}
            </p>
          </div>
        )}
      </div>
    </>
  );
}

