              >
                {loading ? <Loader /> : "Continue"}
              </Button>

              <button
                type="button"
                onClick={() => setStep("email")}
                className="text-sm text-gray-400 hover:text-white transition-colors w-full text-center"
              >
                ← Use a different email
              </button>
