                <span className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-500">@</span>
                <Input
                  type="text"
                  placeholder="username"
                  value={username}
                  onChange={(e) => setUsernameState(e.target.value)}
                  required
                  className="bg-black border-gray-800 text-white placeholder-gray-500 focus:border-gray-500 focus:ring-1 focus:ring-gray-500 pl-8"
                />
              </div>

              {error && (
                <p className="text-sm text-red-500 text-center">{error}</p>
              )}

              <Button
                type="submit"
                disabled={username.length < 3 || loading}
                className="w-full bg-red-600 text-white font-semibold hover:bg-red-500 disabled:opacity-50 h-10 flex items-center justify-center"
              >
                {loading ? <Loader /> : "Complete Setup"}
              </Button>
            </form>
