        {/* Username Step */}
        {step === "username" && (
          <>
            <h2 className="text-2xl font-bold text-white mb-3">Choose Username</h2>
            <p className="text-gray-400 mb-6 text-sm leading-relaxed">
              Pick a unique username for your profile
