    setUser(userData);
    setIsMobileDrawerOpen(false);
  };

  const handleLogout = () => {
    const token = localStorage.getItem("auth_token");
    if (token) {
      localStorage.removeItem("auth_token");
      localStorage.removeItem("user");
      setUser(null);
    }
    setIsMobileDrawerOpen(false);
  };

