                    value={username}
                    onChange={(e) => setUsernameState(e.target.value)}
                    required
                    className={`bg-black border-gray-800 text-white placeholder-gray-500 focus:border-gray-500 focus:ring-1 focus:ring-gray-500 pl-8 pr-10 ${
